insert into lieux (slug, nom, category, department, country, address, google_maps_url, source, lat, lng, rating, reviews_count, description, horaires, contact, website, prix, price_level, duree, alerte, photo_credit, photo_source, tags, ideal_pour, photos, verified, infos_estimees) values ('eglise-sainte-rita', 'Église Sainte Rita', 'site_touristique', 'Littoral', 'Bénin', 'Cotonou, Littoral', 'https://www.google.com/maps/search/?api=1&query=6.3789476,2.3881503', 'Vérifié (Google Places)', 6.3789476, 2.3881503, null, null, 'Au cœur du quartier qui porte son nom, l''église Sainte-Rita est l''un des repères les plus connus de Cotonou. On y passe pour une messe, un moment de calme ou simplement pour voir l''animation du carrefour voisin.', null, null, null, 'Entrée libre (lieu de culte)', 'gratuit', 'courte', null, null, null, array['spiritualite','culture']::text[], array['solo','couple','famille']::text[], '{}'::text[], true, false) on conflict (slug) do update set nom = excluded.nom, category = excluded.category, department = excluded.department, country = excluded.country, address = excluded.address, google_maps_url = excluded.google_maps_url, source = excluded.source, lat = excluded.lat, lng = excluded.lng, rating = excluded.rating, reviews_count = excluded.reviews_count, description = excluded.description, horaires = excluded.horaires, contact = excluded.contact, website = excluded.website, prix = excluded.prix, price_level = excluded.price_level, duree = excluded.duree, alerte = excluded.alerte, photo_credit = excluded.photo_credit, photo_source = excluded.photo_source, tags = excluded.tags, ideal_pour = excluded.ideal_pour, photos = excluded.photos, verified = excluded.verified, infos_estimees = excluded.infos_estimees, updated_at = now();
insert into lieux (slug, nom, category, department, country, address, google_maps_url, source, lat, lng, rating, reviews_count, description, horaires, contact, website, prix, price_level, duree, alerte, photo_credit, photo_source, tags, ideal_pour, photos, verified, infos_estimees) values ('fondation-zinsou', 'Fondation Zinsou', 'site_touristique', 'Littoral', 'Bénin', 'Av. Germain Olory Togbé, Cotonou', 'https://www.google.com/maps/search/?api=1&query=6.3625604,2.4206323', 'Vérifié (Google Places)', 6.3625604, 2.4206323, 4.3, 88, 'Créée en 2005 par Marie-Cécile Zinsou, la fondation a fait de l''art contemporain africain une sortie gratuite et accessible à tous. Expositions temporaires, médiathèque et ateliers pour enfants : une adresse culturelle incontournable de Cotonou.', 'Musée principal (Zongo/Haie Vive) : lun 14h-19h, mar-sam 10h-19h, fermé dim. LAB (Fidjrossè) : lun-ven ~9h-18h, fermé dim.', '+229 91 20 70 19', 'https://www.fondation-zinsou.org', 'Entrée gratuite', 'gratuit', 'courte', null, null, null, array['art','culture']::text[], array['solo','couple','amis','famille']::text[], '{}'::text[], true, false) on conflict (slug) do update set nom = excluded.nom, category = excluded.category, department = excluded.department, country = excluded.country, address = excluded.address, google_maps_url = excluded.google_maps_url, source = excluded.source, lat = excluded.lat, lng = excluded.lng, rating = excluded.rating, reviews_count = excluded.reviews_count, description = excluded.description, horaires = excluded.horaires, contact = excluded.contact, website = excluded.website, prix = excluded.prix, price_level = excluded.price_level, duree = excluded.duree, alerte = excluded.alerte, photo_credit = excluded.photo_credit, photo_source = excluded.photo_source, tags = excluded.tags, ideal_pour = excluded.ideal_pour, photos = excluded.photos, verified = excluded.verified, infos_estimees = excluded.infos_estimees, updated_at = now();
insert into lieux (slug, nom, category, department, country, address, google_maps_url, source, lat, lng, rating, reviews_count, description, horaires, contact, website, prix, price_level, duree, alerte, photo_credit, photo_source, tags, ideal_pour, photos, verified, infos_estimees) values ('plage-de-fidjrosse', 'Plage de Fidjrossè', 'loisir', 'Littoral', 'Bénin', 'Cotonou, Littoral', 'https://www.google.com/maps/search/?api=1&query=6.3483034,2.3666226', 'Vérifié (Google Places)', 6.3483034, 2.3666226, 3.6, 72, 'La plage des Cotonois : sable clair, maquis et paillotes les pieds dans le sable, ambiance animée le week-end. Idéale pour une fin d''après-midi face à l''océan — la baignade y est dangereuse à cause des courants, on profite plutôt du rivage.', null, null, null, 'Accès libre', 'gratuit', 'courte', null, 'Photo : Saliousoft — CC BY-SA 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Jeunes_sur_la_plage_de_Fidjross%C3%A8_%C3%A0_Cotonou_au_B%C3%A9nin.jpg', array['plage','detente']::text[], array['couple','amis','famille']::text[], array['https://thumb.wikimedia.org/wikipedia/commons/thumb/8/89/Jeunes_sur_la_plage_de_Fidjross%C3%A8_%C3%A0_Cotonou_au_B%C3%A9nin.jpg/1920px-Jeunes_sur_la_plage_de_Fidjross%C3%A8_%C3%A0_Cotonou_au_B%C3%A9nin.jpg']::text[], true, false) on conflict (slug) do update set nom = excluded.nom, category = excluded.category, department = excluded.department, country = excluded.country, address = excluded.address, google_maps_url = excluded.google_maps_url, source = excluded.source, lat = excluded.lat, lng = excluded.lng, rating = excluded.rating, reviews_count = excluded.reviews_count, description = excluded.description, horaires = excluded.horaires, contact = excluded.contact, website = excluded.website, prix = excluded.prix, price_level = excluded.price_level, duree = excluded.duree, alerte = excluded.alerte, photo_credit = excluded.photo_credit, photo_source = excluded.photo_source, tags = excluded.tags, ideal_pour = excluded.ideal_pour, photos = excluded.photos, verified = excluded.verified, infos_estimees = excluded.infos_estimees, updated_at = now();
insert into lieux (slug, nom, category, department, country, address, google_maps_url, source, lat, lng, rating, reviews_count, description, horaires, contact, website, prix, price_level, duree, alerte, photo_credit, photo_source, tags, ideal_pour, photos, verified, infos_estimees) values ('statue-de-l-amazone-place-du-souvenir', 'Statue de l''Amazone (Place du Souvenir)', 'site_touristique', 'Littoral', 'Bénin', 'Rte de l''Aéroport, Cotonou', 'https://www.google.com/maps/search/?api=1&query=6.3536986,2.4049056', 'Vérifié (Google Places)', 6.3536986, 2.4049056, 4.5, 15, 'Inaugurée en 2022, la statue de l''Amazone culmine à près de 30 mètres et rend hommage aux guerrières du royaume du Dahomey. L''esplanade de la Place du Souvenir se prête à une courte visite, idéalement au coucher du soleil.', null, null, null, 'Accès libre (espace public)', 'gratuit', 'courte', null, 'Photo : Rachad sanoussi — CC BY-SA 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Vue_de_gauche_de_la_statue_%C3%A0_la_Place_du_souvenir.jpg', array['histoire','culture']::text[], array['solo','couple','amis','famille']::text[], array['https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9a/Vue_de_gauche_de_la_statue_%C3%A0_la_Place_du_souvenir.jpg/1920px-Vue_de_gauche_de_la_statue_%C3%A0_la_Place_du_souvenir.jpg']::text[], true, false) on conflict (slug) do update set nom = excluded.nom, category = excluded.category, department = excluded.department, country = excluded.country, address = excluded.address, google_maps_url = excluded.google_maps_url, source = excluded.source, lat = excluded.lat, lng = excluded.lng, rating = excluded.rating, reviews_count = excluded.reviews_count, description = excluded.description, horaires = excluded.horaires, contact = excluded.contact, website = excluded.website, prix = excluded.prix, price_level = excluded.price_level, duree = excluded.duree, alerte = excluded.alerte, photo_credit = excluded.photo_credit, photo_source = excluded.photo_source, tags = excluded.tags, ideal_pour = excluded.ideal_pour, photos = excluded.photos, verified = excluded.verified, infos_estimees = excluded.infos_estimees, updated_at = now();
insert into lieux (slug, nom, category, department, country, address, google_maps_url, source, lat, lng, rating, reviews_count, description, horaires, contact, website, prix, price_level, duree, alerte, photo_credit, photo_source, tags, ideal_pour, photos, verified, infos_estimees) values ('stade-de-l-amitie', 'Stade de l''Amitié', 'loisir', 'Littoral', 'Bénin', 'Kouhounou, Cotonou', 'https://www.google.com/maps/search/?api=1&query=6.3859642,2.3794872', 'Vérifié (Google Places)', 6.3859642, 2.3794872, 3.3, 15, 'Le stade Général Mathieu Kérékou, ex-stade de l''Amitié, accueille jusqu''à 35 000 spectateurs. C''est ici que vibrent les grands matchs des Guépards du Bénin et les rassemblements populaires de Cotonou.', null, '+229 21 38 17 84', null, null, 'economique', 'demi_journee', null, null, null, array['sport']::text[], array['amis','famille']::text[], '{}'::text[], true, true) on conflict (slug) do update set nom = excluded.nom, category = excluded.category, department = excluded.department, country = excluded.country, address = excluded.address, google_maps_url = excluded.google_maps_url, source = excluded.source, lat = excluded.lat, lng = excluded.lng, rating = excluded.rating, reviews_count = excluded.reviews_count, description = excluded.description, horaires = excluded.horaires, contact = excluded.contact, website = excluded.website, prix = excluded.prix, price_level = excluded.price_level, duree = excluded.duree, alerte = excluded.alerte, photo_credit = excluded.photo_credit, photo_source = excluded.photo_source, tags = excluded.tags, ideal_pour = excluded.ideal_pour, photos = excluded.photos, verified = excluded.verified, infos_estimees = excluded.infos_estimees, updated_at = now();
insert into lieux (slug, nom, category, department, country, address, google_maps_url, source, lat, lng, rating, reviews_count, description, horaires, contact, website, prix, price_level, duree, alerte, photo_credit, photo_source, tags, ideal_pour, photos, verified, infos_estimees) values ('route-des-esclaves', 'Route des Esclaves', 'site_touristique', 'Atlantique', 'Bénin', 'Ouidah, Atlantique', 'https://www.google.com/maps/search/?api=1&query=6.3566471,2.0888293', 'Vérifié (Google Places)', 6.3566471, 2.0888293, 4.6, 5, 'Un peu plus de trois kilomètres entre la place des enchères et la plage : la Route des Esclaves retrace le dernier chemin des captifs déportés vers les Amériques. L''arbre de l''Oubli, le mémorial de Zoungbodji et la Porte du Non-Retour, érigée en 1995, en marquent les étapes.', '9h-18h tous les jours', null, null, 'Parcours en accès libre ; guide en option', 'gratuit', 'demi_journee', null, 'Photo : Hinnou Gontran Serge — CC BY-SA 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Route_des_esclaves_%C3%A0_Ouidah_au_B%C3%A9nin.jpg', array['histoire','culture']::text[], array['solo','couple','amis','famille']::text[], array['https://thumb.wikimedia.org/wikipedia/commons/thumb/9/95/Route_des_esclaves_%C3%A0_Ouidah_au_B%C3%A9nin.jpg/1920px-Route_des_esclaves_%C3%A0_Ouidah_au_B%C3%A9nin.jpg']::text[], true, true) on conflict (slug) do update set nom = excluded.nom, category = excluded.category, department = excluded.department, country = excluded.country, address = excluded.address, google_maps_url = excluded.google_maps_url, source = excluded.source, lat = excluded.lat, lng = excluded.lng, rating = excluded.rating, reviews_count = excluded.reviews_count, description = excluded.description, horaires = excluded.horaires, contact = excluded.contact, website = excluded.website, prix = excluded.prix, price_level = excluded.price_level, duree = excluded.duree, alerte = excluded.alerte, photo_credit = excluded.photo_credit, photo_source 