insert into lieux (slug, nom, category, department, country, address, google_maps_url, source, lat, lng, rating, reviews_count, description, horaires, contact, website, prix, price_level, duree, alerte, photo_credit, photo_source, tags, ideal_pour, photos, verified, infos_estimees) values ('temple-des-pythons', 'Temple des Pythons', 'site_touristique', 'Atlantique', 'Bénin', 'Ouidah, Atlantique', 'https://www.google.com/maps/search/?api=1&query=6.3595647,2.0851368', 'Vérifié (Google Places)', 6.3595647, 2.0851368, 3.6, 142, 'Face à la basilique de l''Immaculée Conception, ce sanctuaire vaudou dédié à Dangbé, le dieu python, abrite des dizaines de pythons royaux. Les guides racontent la place de ces serpents sacrés dans l''histoire de Ouidah — les plus téméraires les portent autour du cou.', 'Tous les jours, environ 8h-19h', '+229 41 44 87 06', null, '≈ 2 000 FCFA / pers. (tarif relevé en 2021)', 'economique', 'courte', null, 'Photo : Gildaskiki — CC BY-SA 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Temple_des_Pythons_de_Ouidah_02.jpg', array['spiritualite','culture']::text[], array['solo','couple','amis','famille']::text[], array['https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0b/Temple_des_Pythons_de_Ouidah_02.jpg/1920px-Temple_des_Pythons_de_Ouidah_02.jpg']::text[], true, false) on conflict (slug) do update set nom = excluded.nom, category = excluded.category, department = excluded.department, country = excluded.country, address = excluded.address, google_maps_url = excluded.google_maps_url, source = excluded.source, lat = excluded.lat, lng = excluded.lng, rating = excluded.rating, reviews_count = excluded.reviews_count, description = excluded.description, horaires = excluded.horaires, contact = excluded.contact, website = excluded.website, prix = excluded.prix, price_level = excluded.price_level, duree = excluded.duree, alerte = excluded.alerte, photo_credit = excluded.photo_credit, photo_source = excluded.photo_source, tags = excluded.tags, ideal_pour = excluded.ideal_pour, photos = excluded.photos, verified = excluded.verified, infos_estimees = excluded.infos_estimees, updated_at = now();
insert into lieux (slug, nom, category, department, country, address, google_maps_url, source, lat, lng, rating, reviews_count, description, horaires, contact, website, prix, price_level, duree, alerte, photo_credit, photo_source, tags, ideal_pour, photos, verified, infos_estimees) values ('foret-sacree-de-kpasse', 'Forêt sacrée de Kpassè', 'site_touristique', 'Atlantique', 'Bénin', 'Ouidah, Atlantique', 'https://www.google.com/maps/search/?api=1&query=6.3653416,2.0958514', 'Vérifié (Google Places)', 6.3653416, 2.0958514, 4.3, 10, 'Selon la tradition, le roi Kpassè, fondateur de Ouidah, s''y serait changé en iroko pour échapper à ses ennemis. Sous les grands arbres, des sculptures de divinités vaudou installées pour le festival de 1993 jalonnent une balade paisible en plein centre-ville.', null, null, null, '≈ 1 100 FCFA / pers. (tarif relevé en 2021)', 'economique', 'courte', null, 'Photo : David Stanley from Nanaimo, Canada — CC BY 2.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Foret_Sacree_de_Kpasse_(20733814183).jpg', array['spiritualite','nature','culture']::text[], array['solo','couple','amis','famille']::text[], array['https://upload.wikimedia.org/wikipedia/commons/f/f8/Foret_Sacree_de_Kpasse_%2820733814183%29.jpg']::text[], true, false) on conflict (slug) do update set nom = excluded.nom, category = excluded.category, department = excluded.department, country = excluded.country, address = excluded.address, google_maps_url = excluded.google_maps_url, source = excluded.source, lat = excluded.lat, lng = excluded.lng, rating = excluded.rating, reviews_count = excluded.reviews_count, description = excluded.description, horaires = excluded.horaires, contact = excluded.contact, website = excluded.website, prix = excluded.prix, price_level = excluded.price_level, duree = excluded.duree, alerte = excluded.alerte, photo_credit = excluded.photo_credit, photo_source = excluded.photo_source, tags = excluded.tags, ideal_pour = excluded.ideal_pour, photos = excluded.photos, verified = excluded.verified, infos_estimees = excluded.infos_estimees, updated_at = now();
insert into lieux (slug, nom, category, department, country, address, google_maps_url, source, lat, lng, rating, reviews_count, description, horaires, contact, website, prix, price_level, duree, alerte, photo_credit, photo_source, tags, ideal_pour, photos, verified, infos_estimees) values ('fort-portugais-de-ouidah', 'Fort Portugais de Ouidah', 'site_touristique', 'Atlantique', 'Bénin', 'Ouidah, Atlantique', 'https://www.google.com/maps/search/?api=1&query=6.3716474,2.0763253', 'Vérifié (Google Places)', 6.3716474, 2.0763253, 4.0, 79, 'Construit en 1721, l''ancien fort portugais abrite le musée d''histoire de Ouidah et ses quelque 700 objets sur la traite et les liens entre le Bénin, le Brésil et les Caraïbes. Vérifiez l''ouverture avant de vous déplacer : le site a été annoncé en rénovation.', null, '+229 21 34 10 21', null, '≈ 5 000 FCFA / pers. pour le musée d''histoire (tarif 2021, fermeture possible)', 'moyen', 'courte', null, 'Photo : Rachad sanoussi — CC BY-SA 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Le_Fort_Portugais_de_Ouidah.jpg', array['histoire','culture']::text[], array['solo','couple','famille']::text[], array['https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7a/Le_Fort_Portugais_de_Ouidah.jpg/1920px-Le_Fort_Portugais_de_Ouidah.jpg']::text[], true, false) on conflict (slug) do update set nom = excluded.nom, category = excluded.category, department = excluded.department, country = excluded.country, address = excluded.address, google_maps_url = excluded.google_maps_url, source = excluded.source, lat = excluded.lat, lng = excluded.lng, rating = excluded.rating, reviews_count = excluded.reviews_count, description = excluded.description, horaires = excluded.horaires, contact = excluded.contact, website = excluded.website, prix = excluded.prix, price_level = excluded.price_level, duree = excluded.duree, alerte = excluded.alerte, photo_credit = excluded.photo_credit, photo_source = excluded.photo_source, tags = excluded.tags, ideal_pour = excluded.ideal_pour, photos = excluded.photos, verified = excluded.verified, infos_estimees = excluded.infos_estimees, updated_at = now();
insert into lieux (slug, nom, category, department, country, address, google_maps_url, source, lat, lng, rating, reviews_count, description, horaires, contact, website, prix, price_level, duree, alerte, photo_credit, photo_source, tags, ideal_pour, photos, verified, infos_estimees) values ('ganvie', 'Ganvié', 'site_touristique', 'Atlantique', 'Bénin', 'Lac Nokoué, Atlantique', 'https://www.google.com/maps/search/?api=1&query=6.4674443,2.3912944', 'Vérifié (Google Places)', 6.4674443, 2.3912944, 4.4, 69, 'Plus grand village lacustre d''Afrique, Ganvié s''est bâti sur pilotis au milieu du lac Nokoué, où les Tofinu se réfugièrent pour échapper aux razzias esclavagistes. On le découvre en pirogue, entre maisons sur l''eau, marché flottant et techniques de pêche ancestrales.', null, null, null, '≈ 5 000 à 10 500 FCFA / pers. (pirogue + guide, selon taille du groupe)', 'moyen', 'demi_journee', null, 'Photo : jbdodane — CC BY 2.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Pilotis_of_Ganvi%C3%A9_People.jpg', array['culture','aventure']::text[], array['solo','couple','amis','famille']::text[], array['https://thumb.wikimedia.org/wikipedia/commons/thumb/9/95/Pilotis_of_Ganvi%C3%A9_People.jpg/1920px-Pilotis_of_Ganvi%C3%A9_People.jpg']::text[], true, false) on conflict (slug) do update set nom = excluded.nom, category = excluded.category, department = excluded.department, country = excluded.country, address = excluded.address, google_maps_url = excluded.google_maps_url, source = excluded.source, lat = excluded.lat, lng = excluded.lng, rating = excluded.rating, reviews_count = excluded.reviews_count, description = excluded.description, horaires = excluded.horaires, contact = excluded.contact, website = excluded.website, prix = excluded.prix, price_level = excluded.price_level, duree = excluded.duree, alerte = excluded.alerte, photo_credit = excluded.photo_credit, photo_source = excluded.photo_source, tags = excluded.tags, ideal_pour = excluded.ideal_pour, p