insert into lieux (slug, nom, category, department, country, address, google_maps_url, source, lat, lng, rating, reviews_count, description, horaires, contact, website, prix, price_level, duree, alerte, photo_credit, photo_source, tags, ideal_pour, photos, verified, infos_estimees) values ('palais-royal-de-porto-novo', 'Palais royal de Porto-Novo', 'site_touristique', 'Ouémé', 'Bénin', 'Porto-Novo, Ouémé', 'https://www.google.com/maps/search/?api=1&query=6.4691571,2.6248765', 'Vérifié (Google Places)', 6.4691571, 2.6248765, 4.0, 21, 'Le musée Honmè occupe le palais du roi Toffa, qui signa le protectorat avec la France en 1883. Les pièces conservées dans leur état d''origine racontent la vie de cour du royaume de Hogbonou, ancêtre de Porto-Novo.', null, null, null, '≈ 1 000 FCFA / pers.', 'economique', 'courte', null, 'Photo : Rachad sanoussi — CC BY-SA 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Une_vue_de_proche_de_la_devanture_du_Mus%C3%A9e_Honm%C3%A8.jpg', array['histoire','culture']::text[], array['solo','couple','amis','famille']::text[], array['https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a0/Une_vue_de_proche_de_la_devanture_du_Mus%C3%A9e_Honm%C3%A8.jpg/1920px-Une_vue_de_proche_de_la_devanture_du_Mus%C3%A9e_Honm%C3%A8.jpg']::text[], true, false) on conflict (slug) do update set nom = excluded.nom, category = excluded.category, department = excluded.department, country = excluded.country, address = excluded.address, google_maps_url = excluded.google_maps_url, source = excluded.source, lat = excluded.lat, lng = excluded.lng, rating = excluded.rating, reviews_count = excluded.reviews_count, description = excluded.description, horaires = excluded.horaires, contact = excluded.contact, website = excluded.website, prix = excluded.prix, price_level = excluded.price_level, duree = excluded.duree, alerte = excluded.alerte, photo_credit = excluded.photo_credit, photo_source = excluded.photo_source, tags = excluded.tags, ideal_pour = excluded.ideal_pour, photos = excluded.photos, verified = excluded.verified, infos_estimees = excluded.infos_estimees, updated_at = now();
insert into lieux (slug, nom, category, department, country, address, google_maps_url, source, lat, lng, rating, reviews_count, description, horaires, contact, website, prix, price_level, duree, alerte, photo_credit, photo_source, tags, ideal_pour, photos, verified, infos_estimees) values ('musee-da-silva', 'Musée da Silva', 'site_touristique', 'Ouémé', 'Bénin', 'Porto-Novo, Ouémé', 'https://www.google.com/maps/search/?api=1&query=6.4708524,2.6205004', 'Vérifié (Google Places)', 6.4708524, 2.6205004, 3.9, 21, 'Installé dans une belle demeure afro-brésilienne de 1870, le musée da Silva retrace l''histoire des Agudas, ces anciens esclaves revenus du Brésil. Mobilier d''époque et photos anciennes font revivre l''architecture et le métissage culturel de Porto-Novo.', null, '+229 96 53 60 42', null, null, 'economique', 'courte', null, 'Photo : Ksperentos — CC BY-SA 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Mus%C3%A9e_da_Silva.jpg', array['histoire','culture','art']::text[], array['solo','couple','famille']::text[], array['https://thumb.wikimedia.org/wikipedia/commons/thumb/1/10/Mus%C3%A9e_da_Silva.jpg/1920px-Mus%C3%A9e_da_Silva.jpg']::text[], true, true) on conflict (slug) do update set nom = excluded.nom, category = excluded.category, department = excluded.department, country = excluded.country, address = excluded.address, google_maps_url = excluded.google_maps_url, source = excluded.source, lat = excluded.lat, lng = excluded.lng, rating = excluded.rating, reviews_count = excluded.reviews_count, description = excluded.description, horaires = excluded.horaires, contact = excluded.contact, website = excluded.website, prix = excluded.prix, price_level = excluded.price_level, duree = excluded.duree, alerte = excluded.alerte, photo_credit = excluded.photo_credit, photo_source = excluded.photo_source, tags = excluded.tags, ideal_pour = excluded.ideal_pour, photos = excluded.photos, verified = excluded.verified, infos_estimees = excluded.infos_estimees, updated_at = now();
insert into lieux (slug, nom, category, department, country, address, google_maps_url, source, lat, lng, rating, reviews_count, description, horaires, contact, website, prix, price_level, duree, alerte, photo_credit, photo_source, tags, ideal_pour, photos, verified, infos_estimees) values ('musee-ethnographique-alexandre-senou-adande', 'Musée ethnographique Alexandre Sènou Adandé', 'site_touristique', 'Ouémé', 'Bénin', 'RNIE1, Porto-Novo', 'https://www.google.com/maps/search/?api=1&query=6.4731824,2.617385', 'Vérifié (Google Places)', 6.4731824, 2.617385, 3.7, 29, 'Fondé en 1957 dans une maison coloniale, le musée Adandé réunit masques guèlèdè, statuettes et objets rituels venus de tout le pays. Une introduction claire à la diversité des cultures béninoises, avant de partir les découvrir sur le terrain.', null, '+229 20 21 25 54', null, null, 'economique', 'courte', null, null, null, array['culture','art']::text[], array['solo','couple','famille']::text[], '{}'::text[], true, true) on conflict (slug) do update set nom = excluded.nom, category = excluded.category, department = excluded.department, country = excluded.country, address = excluded.address, google_maps_url = excluded.google_maps_url, source = excluded.source, lat = excluded.lat, lng = excluded.lng, rating = excluded.rating, reviews_count = excluded.reviews_count, description = excluded.description, horaires = excluded.horaires, contact = excluded.contact, website = excluded.website, prix = excluded.prix, price_level = excluded.price_level, duree = excluded.duree, alerte = excluded.alerte, photo_credit = excluded.photo_credit, photo_source = excluded.photo_source, tags = excluded.tags, ideal_pour = excluded.ideal_pour, photos = excluded.photos, verified = excluded.verified, infos_estimees = excluded.infos_estimees, updated_at = now();
insert into lieux (slug, nom, category, department, country, address, google_maps_url, source, lat, lng, rating, reviews_count, description, horaires, contact, website, prix, price_level, duree, alerte, photo_credit, photo_source, tags, ideal_pour, photos, verified, infos_estimees) values ('centre-songhai', 'Centre Songhaï', 'site_touristique', 'Ouémé', 'Bénin', 'Route de Ouando, Porto-Novo', 'https://www.google.com/maps/search/?api=1&query=6.4994544,2.6147924', 'Vérifié (Google Places)', 6.4994544, 2.6147924, null, null, 'Fondé en 1985 par le père Godfrey Nzamujo, Songhaï est devenu une référence de l''agriculture intégrée en Afrique : « rien ne se perd, tout se transforme ». La visite guidée d''une heure parcourt cultures, élevages et ateliers, avant une pause au restaurant ou à la boutique de produits maison.', 'Visites guidées lun-ven 8h30/10h30/15h30/17h, sam 8h30/10h30/16h', '+229 01 60 93 33 34', 'https://songhai.org', 'Visite guidée d''environ 1 h ; restaurant sur place (≈ 1 200 à 3 500 FCFA le plat)', 'economique', 'courte', null, null, null, array['nature','culture']::text[], array['solo','couple','amis','famille']::text[], '{}'::text[], true, true) on conflict (slug) do update set nom = excluded.nom, category = excluded.category, department = excluded.department, country = excluded.country, address = excluded.address, google_maps_url = excluded.google_maps_url, source = excluded.source, lat = excluded.lat, lng = excluded.lng, rating = excluded.rating, reviews_count = excluded.reviews_count, description = excluded.description, horaires = excluded.horaires, contact = excluded.contact, website = excluded.website, prix = excluded.prix, price_level = excluded.price_level, duree = excluded.duree, alerte = excluded.alerte, photo_credit = excluded.photo_credit, photo_source = excluded.photo_source, tags = excluded.tags, ideal_pour = excluded.ideal_pour, photos = excluded.photos, verified = excluded.verified, infos_estimees = excluded.infos_estimees, updated_at = now();
insert into lieux (slug, nom, category, department, country, address, google_maps_url, source, lat, lng, rating, reviews_count, description, horaires, contact, website, prix, price_level, duree, alerte, photo_credit, photo_source, tags, ideal_pour, photos, verified, infos_estimees) values ('cathedrale-notre-dame-de-porto-novo', 'Cathédrale Notre-Dame de Porto-Novo', 'site_touristique', 'Ouémé', 'Bénin', 'RNIE1, Porto-Novo', 'https://www.google.com/maps/search/?api=1&query=6.4721065,2.6197026', 'Vérifié (Google Places)', 6.4721065, 2.6197026, null, null, 'La cathédrale Notre-Dame-de-l''Immaculée-Conception affiche une façade colorée inspirée de l''architecture afro-brésilienne du vieux Porto-Novo. Un arrêt rapide pendant une balade dans le centre historique de la capitale.', 'Messes semaine 6h, 12h45, 18h ; dimanche 7h, 9h, 10h30, 19h', null, null, 'Entrée libre (lieu de culte)', 'gratuit', 'courte', null, 'Photo : Mhope2010 — CC BY-SA 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Cath%C3%A9drale_Notre-Dame_de_l%27Immacul%C3%A9e_Conception_de_Porto-Novo_2021_01.jpg', array['spiritualite','histoire']::text[], array['solo','couple','famille']::text[], array['https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fa/Cath%C3%A9drale_Notre-Dame_de_l%27Immacul%C3%A9e_Conception_de_Porto-Novo_2021_01.jpg/1920px-Cath%C3%A9drale_Notre-Dame_de_l%27Immacul%C3%A9e_Conception_de_Porto-Novo_2021_01.jpg']::text[], true, false) on conflict (slug) do update set nom = excluded.nom, category = excluded.category, department = excluded.department, country = excluded.country, address = excluded.address, google_maps_url = excluded.google_maps_url, source = excluded.source, lat = excluded.lat, lng = excluded.lng, rating = excluded.rating, reviews_count = excluded.reviews_count, description = excluded.description, horaires = excluded.horaires, contact = excluded.contact, website = excluded.website, prix = excluded.prix, price_level = excluded.price_level, duree = excluded.duree, alerte = excluded.alerte, photo_credit = excluded.photo_credit, photo_source = excluded.photo_source, tags = excluded.tags, ideal_pour = excluded.ideal_pour, photos = excluded.photos, verified = excluded.verified, infos_estimees = excluded.infos_estimees, updated_at = now();
insert into lieux (slug, nom, category, department, country, address, google_maps_url, source, lat, lng, rating, reviews_count, description, horaires, contact, website, prix, price_level, duree, alerte, photo_credit, photo_source, tags, ideal_pour, photos, verified, infos_estimees) values ('cite-royale-de-ketou', 'Cité royale de Kétou', 'site_touristique', 'Plateau', 'Bénin', 'Kétou, Plateau', 'https://www.google.com/maps/search/?api=1&query=7.3603376,2.6040436', 'Vérifié (Google Places)', 7.3603376, 2.6040436, null, null, 'Kétou, cité yoruba fondée au XIVe siècle, est le berceau du Guèlèdè, inscrit au patrimoine immatériel de l''UNESCO. On y découvre la cour royale, les remparts de terre et la célèbre porte Akaba Idéna.', null, null, null, null, 'economique', 'demi_journee', null, null, null, array['histoire','culture']::text[], array['solo','couple','amis','famille']::text[], '{}'::text[], true, true) on conflict (slug) do update set nom = excluded.nom, category = excluded.category, department = excluded.department, country = excluded.country, address = excluded.address, google_maps_url = excluded.google_maps_url, source = excluded.source, lat = excluded.lat, lng = excluded.lng, rating = excluded.rating, reviews_count = excluded.reviews_count, description = excluded.description, horaires = excluded.horaires, contact = excluded.contact, website = excluded.website, prix = excluded.prix, price_level = excluded.price_level, duree = excluded.duree, alerte = excluded.alerte, photo_credit = excluded.photo_credit, photo_source = excluded.photo_source, tags = excluded.tags, ideal_pour = excluded.ideal_pour, photos = excluded.photos, verified = excluded.verified, infos_estimees = excluded.infos_estimees, updated_at = now();
insert into lieux (slug, nom, category, department, country, address, google_maps_url, source, lat, lng, rating, reviews_count, description, horaires, contact, website, prix, price_level, duree, alerte, photo_credit, photo_source, tags, ideal_pour, photos, verified, infos_estimees) values ('musee-akaba-idena', 'Musée Akaba Idena', 'site_touristique', 'Plateau', 'Bénin', 'Kétou, Plateau', 'https://www.google.com/maps/search/?api=1&query=7.3634919,2.6016927', 'Vérifié (Google Places)', 7.3634919, 2.6016927, null, null, 'Akaba Idéna, la « porte magique », gardait l''entrée de Kétou ; reconstruite en 1894 après la destruction de la ville par le royaume d''Abomey, elle abrite des autels des divinités yoruba. Le site est en travaux de réhabilitation : renseignez-vous avant de vous déplacer.', null, null, null, null, 'economique', 'courte', null, 'Photo : Rachad sanoussi — CC BY-SA 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:La_porte_pour_femme_du_mus%C3%A9e_Akaba_idena.jpg', array['histoire','culture']::text[], array['solo','couple','famille']::text[], array['https://thumb.wikimedia.org/wikipedia/commons/thumb/7/74/La_porte_pour_femme_du_mus%C3%A9e_Akaba_idena.jpg/1920px-La_porte_pour_femme_du_mus%C3%A9e_Akaba_idena.jpg']::text[], true, true) on conflict (slug) do update set nom = excluded.nom, category = excluded.category, department = excluded.department, country = excluded.country, address = excluded.address, google_maps_url = excluded.google_maps_url, source = excluded.source, lat = excluded.lat, lng = excluded.lng, rating = excluded.rating, reviews_count = excluded.reviews_count, description = excluded.description, horaires = excluded.horaires, contact = excluded.contact, website = excluded.website, prix = excluded.prix, price_level = excluded.price_level, duree = excluded.duree, alerte = excluded.alerte, photo_credit = excluded.photo_credit, photo_source = excluded.photo_source, tags = excluded.tags, ideal_pour = excluded.ideal_pour, photos = excluded.photos, verified = excluded.verified, infos_estimees = excluded.infos_estimees, updated_at = now();
insert into lieux (slug, nom, category, department, country, address, google_maps_url, source, lat, lng, rating, reviews_count, description, horaires, contact, website, prix, price_level, duree, alerte, photo_credit, photo_source, tags, ideal_pour, photos, verified, infos_estimees) values ('ville-de-pobe', 'Ville de Pobè', 'site_touristique', 'Plateau', 'Bénin', 'Pobè, Plateau', 'https://www.google.com/maps/search/?api=1&query=6.9832415,2.6636066', 'Vérifié (Google Places)', 6.9832415, 2.6636066, null, null, 'Chef-lieu du Plateau, Pobè vit au rythme de la culture yoruba-nago et des palmeraies qui l''entourent. Une étape authentique, loin des circuits classiques, pour qui explore l''est du pays.', null, null, null, 'Découverte libre de la ville', 'gratuit', 'demi_journee', null, null, null, array['culture']::text[], array['solo','couple','amis']::text[], '{}'::text[], true, true) on conflict (slug) do update set nom = excluded.nom, category = excluded.category, department = excluded.department, country = excluded.country, address = excluded.address, google_maps_url = excluded.google_maps_url, source = excluded.source, lat = excluded.lat, lng = excluded.lng, rating = excluded.rating, reviews_count = excluded.reviews_count, description = excluded.description, horaires = excluded.horaires, contact = excluded.contact, website = excluded.website, prix = excluded.prix, price_level = excluded.price_level, duree = excluded.duree, alerte = excluded.alerte, photo_credit = excluded.photo_credit, photo_source = excluded.photo_source, tags = excluded.tags, ideal_pour = excluded.ideal_pour, photos = excluded.photos, verified = excluded.verified, infos_estimees = excluded.infos_estimees, updated_at = now();
insert into lieux (slug, nom, category, department, country, address, google_maps_url, source, lat, lng, rating, reviews_count, description, horaires, contact, website, prix, price_level, duree, alerte, photo_credit, photo_source, tags, ideal_pour, photos, verified, infos_estimees) values ('palais-royaux-d-abomey', 'Palais royaux d''Abomey', 'site_touristique', 'Zou', 'Bénin', 'Abomey, Zou', 'https://www.google.com/maps/search/?api=1&query=7.1855024,1.997943', 'Vérifié (Google Places)', 7.1855024, 1.997943, 3.7, 105, 'Douze rois du Dahomey se sont succédé ici de 1625 à 1900, chacun bâtissant son propre palais. Classé à l''UNESCO depuis 1985, le site dévoile ses bas-reliefs, trônes et récits de la cour, avec les palais restaurés de Ghézo et de Glèlè.', 'Tous les jours, 9h-18h', '+229 22 50 03 14', null, '≈ 3 000 à 5 000 FCFA / pers.', 'economique', 'demi_journee', null, 'Photo : Azogbonon — CC BY-SA 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Palais_royaux_d%27Abomey_3.jpg', array['histoire','culture']::text[], array['solo','couple','amis','famille']::text[], array['https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a8/Palais_royaux_d%27Abomey_3.jpg/1920px-Palais_royaux_d%27Abomey_3.jpg']::text[], true, false) on conflict (slug) do update set nom = excluded.nom, category = excluded.category, department = excluded.department, country = excluded.country, address = excluded.address, google_maps_url = excluded.google_maps_url, source = excluded.source, lat = excluded.lat, lng = excluded.lng, rating = excluded.rating, reviews_count = excluded.reviews_count, description = excluded.description, horaires = excluded.horaires, contact = excluded.contact, website = excluded.website, prix = excluded.prix, price_level = excluded.price_level, duree = excluded.duree, alerte = excluded.alerte, photo_credit = excluded.photo_credit, photo_source = excluded.photo_source, tags = excluded.tags, ideal_pour = excluded.ideal_pour, photos = excluded.photos, verified = excluded.verified, infos_estimees = excluded.infos_estimees, updated_at = now();
insert into lieux (slug, nom, category, department, country, address, google_maps_url, source, lat, lng, rating, reviews_count, description, horaires, contact, website, prix, price_level, duree, alerte, photo_credit, photo_source, tags, ideal_pour, photos, verified, infos_estimees) values ('place-behanzin-place-goho', 'Place Béhanzin (Place Goho)', 'loisir', 'Zou', 'Bénin', 'Abomey, Zou', 'https://www.google.com/maps/search/?api=1&query=7.1842529,2.0078158', 'Vérifié (Google Places)', 7.1842529, 2.0078158, 4.0, 5, 'La place Goho rend hommage à Béhanzin, dernier roi du Dahomey indépendant, figure de la résistance à la conquête coloniale. Sa statue monumentale accueille les visiteurs à l''entrée d''Abomey. (Un état d''entretien dégradé a été signalé par la presse locale.)', null, null, null, 'Accès libre (espace public)', 'gratuit', 'courte', null, null, null, array['histoire']::text[], array['solo','couple','amis','famille']::text[], '{}'::text[], true, false) on conflict (slug) do update set nom = excluded.nom, category = excluded.category, department = excluded.department, country = excluded.country, address = excluded.address, google_maps_url = excluded.google_maps_url, source = excluded.source, lat = excluded.lat, lng = excluded.lng, rating = excluded.rating, reviews_count = excluded.reviews_count, description = excluded.description, horaires = excluded.horaires, contact = excluded.contact, website = excluded.website, prix = excluded.prix, price_level = excluded.price_level, duree = excluded.duree, alerte = excluded.alerte, photo_credit = excluded.photo_credit, photo_source = excluded.photo_source, tags = excluded.tags, ideal_pour = excluded.ideal_pour, photos = excluded.photos, verified = excluded.verified, infos_estimees = excluded.infos_estimees, updated_at = now();
insert into lieux (slug, nom, category, department, country, address, google_maps_url, source, lat, lng, rating, reviews_count, description, horaires, contact, website, prix, price_level, duree, alerte, photo_credit, photo_source, tags, ideal_pour, photos, verified, infos_estimees) values ('foret-classee-de-la-lama', 'Forêt classée de la Lama', 'loisir', 'Atlantique/Zou', 'Bénin', 'Toffo, Atlantique / Zogbodomey, Zou', 'https://www.google.com/maps/search/?api=1&query=6.9179281,2.1662158', 'Vérifié (Google Places)', 6.9179281, 2.1662158, null, null, 'Au cœur de ses 16 000 hectares, la forêt de la Lama protège un noyau de forêt dense où vit le singe à ventre rouge, une espèce qu''on ne trouve qu''au Bénin. Une sortie nature à organiser avec un guide, entre Toffo et Zogbodomey.', null, null, null, null, 'moyen', 'journee', null, 'Photo : Padonou Dotou — CC BY-SA 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:All%C3%A9e_verte_pour_des_circuits_%C3%A9cotouristiques_dans_la_for%C3%AAts_de_la_Lama_dans_la_commune_de_Zogbodomey_au_B%C3%A9nin.jpg', array['nature','faune','aventure']::text[], array['amis','famille']::text[], array['https://thumb.wikimedia.org/wikipedia/commons/thumb/6/66/All%C3%A9e_verte_pour_des_circuits_%C3%A9cotouristiques_dans_la_for%C3%AAts_de_la_Lama_dans_la_commune_de_Zogbodomey_au_B%C3%A9nin.jpg/1920px-All%C3%A9e_verte_pour_des_circuits_%C3%A9cotouristiques_dans_la_for%C3%AAts_de_la_Lama_dans_la_commune_de_Zogbodomey_au_B%C3%A9nin.jpg']::text[], true, true) on conflict (slug) do update set nom = excluded.nom, category = excluded.category, department = excluded.department, country = excluded.country, address = excluded.address, google_maps_url = excluded.google_maps_url, source = excluded.source, lat = excluded.lat, lng = excluded.lng, rating = excluded.rating, reviews_count = excluded.reviews_count, description = excluded.description, horaires = excluded.horaires, contact = excluded.contact, website = excluded.website, prix = ex