insert into lieux (slug, nom, category, department, country, address, google_maps_url, source, lat, lng, rating, reviews_count, description, horaires, contact, website, prix, price_level, duree, alerte, photo_credit, photo_source, tags, ideal_pour, photos, verified, infos_estimees) values ('grotte-mariale-de-dassa-zoume', 'Grotte mariale de Dassa-Zoumé', 'site_touristique', 'Collines', 'Bénin', 'Dassa-Zoumé, Collines', 'https://www.google.com/maps/search/?api=1&query=7.7752876,2.1865136', 'Vérifié (Google Places)', 7.7752876, 2.1865136, null, null, 'Nichée dans l''une des 41 collines de Dassa-Zoumé, la grotte Notre-Dame d''Arigbo est le plus grand lieu de pèlerinage du pays depuis 1954. Le week-end du 15 août, des milliers de fidèles y convergent ; le reste de l''année, le site invite au calme.', 'Ouvert toute l''année ; grand pèlerinage fin août', null, null, 'Accès libre (lieu de pèlerinage)', 'gratuit', 'demi_journee', null, null, null, array['spiritualite','nature']::text[], array['solo','couple','amis','famille']::text[], '{}'::text[], true, true) on conflict (slug) do update set nom = excluded.nom, category = excluded.category, department = excluded.department, country = excluded.country, address = excluded.address, google_maps_url = excluded.google_maps_url, source = excluded.source, lat = excluded.lat, lng = excluded.lng, rating = excluded.rating, reviews_count = excluded.reviews_count, description = excluded.description, horaires = excluded.horaires, contact = excluded.contact, website = excluded.website, prix = excluded.prix, price_level = excluded.price_level, duree = excluded.duree, alerte = excluded.alerte, photo_credit = excluded.photo_credit, photo_source = excluded.photo_source, tags = excluded.tags, ideal_pour = excluded.ideal_pour, photos = excluded.photos, verified = excluded.verified, infos_estimees = excluded.infos_estimees, updated_at = now();
