insert into lieux (slug, nom, category, department, country, address, google_maps_url, source, lat, lng, rating, reviews_count, description, horaires, contact, website, prix, price_level, duree, alerte, photo_credit, photo_source, tags, ideal_pour, photos, verified, infos_estimees) values ('plage-de-grand-popo', 'Plage de Grand-Popo', 'loisir', 'Mono', 'Bénin', 'Grand-Popo, Mono', 'https://www.google.com/maps/search/?api=1&query=6.2639324,1.7417143', 'Vérifié (Google Places)', 6.2639324, 1.7417143, null, null, 'Entre le fleuve Mono et l''océan, Grand-Popo déroule ses kilomètres de sable bordés de cocotiers, à deux pas du Togo. L''endroit parfait pour décrocher un week-end, entre hôtels de plage et balades en lagune — attention aux courants, la baignade y est risquée.', null, null, null, 'Accès libre', 'gratuit', 'demi_journee', null, 'Photo : Ji-Elle — CC BY-SA 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Plage_de_Grand-Popo_en_fin_de_journ%C3%A9e_(1).jpg', array['plage','detente']::text[], array['solo','couple','amis','famille']::text[], array['https://thumb.wikimedia.org/wikipedia/commons/thumb/0/07/Plage_de_Grand-Popo_en_fin_de_journ%C3%A9e_%281%29.jpg/1920px-Plage_de_Grand-Popo_en_fin_de_journ%C3%A9e_%281%29.jpg']::text[], true, false) on conflict (slug) do update set nom = excluded.nom, category = excluded.category, department = excluded.department, country = excluded.country, address = excluded.address, google_maps_url = excluded.google_maps_url, source = excluded.source, lat = excluded.lat, lng = excluded.lng, rating = excluded.rating, reviews_count = excluded.reviews_count, description = excluded.description, horaires = excluded.horaires, contact = excluded.contact, website = excluded.website, prix = excluded.prix, price_level = excluded.price_level, duree = excluded.duree, alerte = excluded.alerte, photo_credit = excluded.photo_credit, photo_source = excluded.photo_source, tags = excluded.tags, ideal_pour = excluded.ideal_pour, phot