insert into lieux (slug, nom, category, department, country, address, google_maps_url, source, lat, lng, rating, reviews_count, description, horaires, contact, website, prix, price_level, duree, alerte, photo_credit, photo_source, tags, ideal_pour, photos, verified, infos_estimees) values ('village-de-possotome', 'Village de Possotomè', 'site_touristique', 'Mono', 'Bénin', 'Possotomè, Bopa, Mono', 'https://www.google.com/maps/search/?api=1&query=6.520838,1.9625132', 'Vérifié (Google Places)', 6.520838, 1.9625132, null, null, 'Sur la rive du lac Ahémé, Possotomè est célèbre pour sa source thermale, dont l''eau minérale est embouteillée et vendue dans tout le pays. On y vient pour le calme, les balades en pirogue et les villages de pêcheurs alentour.', null, '+229 95 28 52 20', 'https://www.ecobenin.org/possotome', null, 'economique', 'demi_journee', null, null, null, array['nature','detente','culture']::text[], array['solo','couple','amis','famille']::text[], '{}'::text[], true, true) on conflict (slug) do update set nom = excluded.nom, category = excluded.category, department = excluded.department, country = excluded.country, address = excluded.address, google_maps_url = excluded.google_maps_url, source = excluded.source, lat = excluded.lat, lng = excluded.lng, rating = excluded.rating, reviews_count = excluded.reviews_count, description = excluded.description, horaires = excluded.horaires, contact = excluded.contact, website = excluded.website, prix = excluded.prix, price_level = excluded.price_level, duree = excluded.duree, alerte = excluded.alerte, photo_credit = excluded.photo_credit, photo_source = excluded.photo_source, tags = excluded.tags, ideal_pour = excluded.ideal_pour, photos = excluded.photos, verified = excluded.verified, infos_estimees = excluded.infos_estimees, updated_at = now();
insert into lieux (slug, nom, category, department, country, address, google_maps_url, source, lat, lng, rating, reviews_count, description, horaires, contact, website, prix, price_level, duree, alerte, photo_credit, photo_source, tags, ideal_pour, photos, verified, infos_estimees) values ('bouche-du-roy', 'Bouche du Roy', 'site_touristique', 'Mono', 'Bénin', 'Grand-Popo, Mono', 'https://www.google.com/maps/search/?api=1&query=6.2922216,1.917286', 'Vérifié (Google Places)', 6.2922216, 1.917286, 4.0, 2, 'Là où le fleuve Mono rejoint l''Atlantique, la Bouche du Roy forme un delta d''îlots, de prairies et de mangroves parmi les mieux préservés du pays. Une excursion en pirogue d''une demi-journée, souvent conclue par des crevettes grillées.', null, '+229 60 63 08 18', 'https://www.boucheduroy.bj', '≈ 10 000 FCFA / pers. en pirogue (réductions possibles en groupe)', 'moyen', 'demi_journee', null, null, null, array['nature','aventure','plage']::text[], array['solo','couple','amis','famille']::text[], '{}'::text[], true, false) on conflict (slug) do update set nom = excluded.nom, category = excluded.category, department = excluded.department, country = excluded.country, address = excluded.address, google_maps_url = excluded.google_maps_url, source = excluded.source, lat = excluded.lat, lng = excluded.lng, rating = excluded.rating, reviews_count = excluded.reviews_count, description = excluded.description, horaires = excluded.horaires, contact = excluded.contact, website = excluded.website, prix = excluded.prix, price_level = excluded.price_level, duree = excluded.duree, alerte = excluded.alerte, photo_credit = excluded.photo_credit, photo_source = excluded.photo_source, tags = excluded.tags, ideal_pour = excluded.ideal_pour, photos = excluded.photos, verified = excluded.verified, infos_estimees = excluded.infos_estimees, updated_at = now();
