insert into lieux (slug, nom, category, department, country, address, google_maps_url, source, lat, lng, rating, reviews_count, description, horaires, contact, website, prix, price_level, duree, alerte, photo_credit, photo_source, tags, ideal_pour, photos, verified, infos_estimees) values ('parc-national-de-la-pendjari', 'Parc national de la Pendjari', 'site_touristique', 'Atacora', 'Bénin', 'Atacora', 'https://www.google.com/maps/search/?api=1&query=11.2481125,1.5983959', 'Vérifié (Google Places)', 11.2481125, 1.5983959, null, null, 'Réserve de biosphère UNESCO depuis 1986, la Pendjari abrite la plus grande population d''éléphants d''Afrique de l''Ouest, ainsi que lions, guépards et hippopotames. Elle forme avec les parcs W et Arly le plus vaste écosystème intact de la région.', 'Ouvert toute l''année ; safaris recommandés 6h-11h et 16h-tombée de la nuit', null, 'https://www.african-parks.org/the-parks/pendjari', 'Entrée ≈ 19 € adulte étranger, ≈ 7 € résident béninois (anciens tarifs), + véhicule et guide', 'eleve', 'sejour', 'Zone formellement déconseillée aux voyageurs (risque d''attaques terroristes et d''enlèvements, frontière nord). Vérifiez les conseils aux voyageurs de votre pays avant tout déplacement.', 'Photo : Gildasjr — CC BY-SA 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Une_vue_du_Parc_de_la_Pendjari.jpg', array['faune','nature','aventure']::text[], array['solo','couple','amis','famille']::text[], array['https://thumb.wikimedia.org/wikipedia/commons/thumb/1/14/Une_vue_du_Parc_de_la_Pendjari.jpg/1920px-Une_vue_du_Parc_de_la_Pendjari.jpg']::text[], true, false) on conflict (slug) do update set nom = excluded.nom, category = excluded.category, department = excluded.department, country = excluded.country, address = excluded.address, google_maps_url = excluded.google_maps_url, source = excluded.source, lat = excluded.lat, lng = excluded.lng, rating = excluded.rating, reviews_count = excluded.reviews_count, description = excluded.description, horaires = excluded.horaires, contact = excluded.contact, website = excluded.website, prix = excluded.prix, price_level = excluded.price_level, duree = excluded.duree, alerte = excluded.alerte, photo_credit = excluded.photo_credit, photo_source = excluded.photo_source, tags = excluded.tags, ideal_pour = excluded.ideal_pour, photos = excluded.photos, verified = excluded.verified, infos_estimees = excluded.infos_estimees, updated_at = now();
insert into lieux (slug, nom, category, department, country, address, google_maps_url, source, lat, lng, rating, reviews_count, description, horaires, contact, website, prix, price_level, duree, alerte, photo_credit, photo_source, tags, ideal_pour, photos, verified, infos_estimees) values ('villages-tata-somba', 'Villages Tata Somba', 'site_touristique', 'Atacora', 'Bénin', 'Natitingou/Boukoumbé, Atacora', 'https://www.google.com/maps/search/?api=1&query=10.3091173,1.3735244', 'Vérifié (Google Places)', 10.3091173, 1.3735244, null, null, 'Les tata somba, maisons-forteresses en terre à étage des Batammariba, ponctuent les collines entre Natitingou et Boukoumbé. Chaque tata reflète l''organisation familiale et spirituelle de ses habitants : une architecture unique, à découvrir avec un guide local.', null, null, null, null, 'economique', 'demi_journee', null, null, null, array['culture','histoire']::text[], array['solo','couple','amis','famille']::text[], '{}'::text[], true, true) on conflict (slug) do update set nom = excluded.nom, category = excluded.category, department = excluded.department, country = excluded.country, address = excluded.address, google_maps_url = excluded.google_maps_url, source = excluded.source, lat = excluded.lat, lng = excluded.lng, rating = excluded.rating, reviews_count = excluded.reviews_count, description = excluded.description, horaires = excluded.horaires, contact = excluded.contact, website = excluded.website, prix = excluded.prix, price_level = excluded.price_level, duree = excluded.duree, alerte = excluded.alerte, photo_credit = excluded.photo_credit, photo_source = excluded.photo_source, tags = excluded.tags, ideal_pour = excluded.ideal_pour, photos = excluded.photos, verified = excluded.verified, infos_estimees = excluded.infos_estimees, updated_at = now();
insert into lieux (slug, nom, category, department, country, address, google_maps_url, source, lat, lng, rating, reviews_count, description, horaires, contact, website, prix, price_level, duree, alerte, photo_credit, photo_source, tags, ideal_pour, photos, verified, infos_estimees) values ('cascades-de-tanougou', 'Cascades de Tanougou', 'loisir', 'Atacora', 'Bénin', 'Tanongou, Atacora', 'https://www.google.com/maps/search/?api=1&query=10.8121477,1.4363443', 'Vérifié (Google Places)', 10.8121477, 1.4363443, null, null, 'Au pied de la chaîne de l''Atacora, près de Tanguiéta, la chute de Tanougou plonge d''une quinzaine de mètres dans un bassin naturel propice à la baignade. Le débit varie fortement selon la saison : elle est à son plus beau après les pluies.', null, null, null, null, 'economique', 'demi_journee', 'Proche des zones frontalières formellement déconseillées du nord. Renseignez-vous sur la situation sécuritaire avant de partir.', 'Photo : KOUAGOU Damien — CC BY-SA 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Chutes_de_Tanongou.jpg', array['nature','aventure','detente']::text[], array['couple','amis','famille']::text[], array['https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0a/Chutes_de_Tanongou.jpg/1920px-Chutes_de_Tanongou.jpg']::text[], true, true) on conflict (slug) do update set nom = excluded.nom, category = excluded.category, department = excluded.department, country = excluded.country, address = excluded.address, google_maps_url = excluded.google_maps_url, source = excluded.source, lat = excluded.lat, lng = excluded.lng, rating = excluded.rating, reviews_count = excluded.reviews_count, description = excluded.description, horaires = excluded.horaires, contact = excluded.contact, website = excluded.website, prix = excluded.prix, price_level = excluded.price_level, duree = excluded.duree, alerte = excluded.alerte, photo_credit = excluded.photo_credit, photo_source = excluded.photo_source, tags = excluded.tags, ideal_pour = excluded.ideal_pour, photos = excluded.photos, verified = excluded.verified, infos_estimees = excluded.infos_estimees, updated_at = now();
insert into lieux (slug, nom, category, department, country, address, google_maps_url, source, lat, lng, rating, reviews_count, description, horaires, contact, website, prix, price_level, duree, alerte, photo_credit, photo_source, tags, ideal_pour, photos, verified, infos_estimees) values ('musee-regional-de-natitingou', 'Musée régional de Natitingou', 'site_touristique', 'Atacora', 'Bénin', 'Natitingou, Atacora', 'https://www.google.com/maps/search/?api=1&query=10.3106873,1.3802711', 'Vérifié (Google Places)', 10.3106873, 1.3802711, null, null, 'Dans un bâtiment colonial réhabilité, le musée régional présente l''habitat et les traditions de l''Atacora, avec des maquettes des différents types de tata somba. Le bon point de départ avant d''aller voir les vraies maisons dans les villages.', 'Lun-Ven 8h30-18h30, Sam-Dim 9h-18h30', '+229 97 88 10 80', null, null, 'economique', 'courte', null, 'Photo : Farid AMADOU BAHLEMAN — CC BY-SA 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:MUS%C3%89E_R%C3%89GIONAL_DE_NATITINGOU.jpg', array['culture','histoire']::text[], array['solo','couple','famille']::text[], array['https://thumb.wikimedia.org/wikipedia/commons/thumb/2/28/MUS%C3%89E_R%C3%89GIONAL_DE_NATITINGOU.jpg/1920px-MUS%C3%89E_R%C3%89GIONAL_DE_NATITINGOU.jpg']::text[], true, true) on conflict (slug) do update set nom = excluded.nom, category = excluded.category, department = excluded.department, country = excluded.country, address = excluded.address, google_maps_url = excluded.google_maps_url, source = excluded.source, lat = excluded.lat, lng = excluded.lng, rating = excluded.rating, reviews_count = excluded.reviews_count, description = excluded.description, horaires = excluded.horaires, contact = excluded.contact, website = excluded.website, prix = excluded.prix, price_level = excluded.price_level, duree = excluded.duree, alerte = excluded.alerte, photo_credit = excluded.photo_credit, photo_source = excluded.photo_source, tags = excluded.tags, ideal