insert into lieux (slug, nom, category, department, country, address, google_maps_url, source, lat, lng, rating, reviews_count, description, horaires, contact, website, prix, price_level, duree, alerte, photo_credit, photo_source, tags, ideal_pour, photos, verified, infos_estimees) values ('musee-de-plein-air-de-parakou', 'Musée de plein air de Parakou', 'site_touristique', 'Borgou', 'Bénin', 'Parakou, Borgou', 'https://www.google.com/maps/search/?api=1&query=9.3279386,2.6174022', 'Vérifié (Google Places)', 9.3279386, 2.6174022, null, null, 'À ciel ouvert, ce musée ethnographique fait découvrir l''habitat traditionnel, les objets et les arts du nord du Bénin. Une visite courte et vivante au cœur de Parakou, la grande ville du Borgou.', 'Tous les jours 9h-12h et 15h-18h30, sauf jours fériés', '+229 23 61 05 78', 'https://tourisme.parakou.bj/2024/01/18/musee-plein-air-et-ethnographique/', null, 'economique', 'courte', null, null, null, array['culture','art']::text[], array['solo','couple','amis','famille']::text[], '{}'::text[], true, true) on conflict (slug) do update set nom = excluded.nom, category = excluded.category, department = excluded.department, country = excluded.country, address = excluded.address, google_maps_url = excluded.google_maps_url, source = excluded.source, lat = excluded.lat, lng = excluded.lng, rating = excluded.rating, reviews_count = excluded.reviews_count, description = excluded.description, horaires = excluded.horaires, contact = excluded.contact, website = excluded.website, prix = excluded.prix, price_level = excluded.price_level, duree = excluded.duree, alerte = excluded.alerte, photo_credit = excluded.photo_credit, photo_source = excluded.photo_source, tags = excluded.tags, ideal_pour = excluded.ideal_pour, photos = excluded.photos, verified = excluded.verified, infos_estimees = excluded.infos_estimees, updated_at = now();
