insert into lieux (slug, nom, category, department, country, address, google_maps_url, source, lat, lng, rating, reviews_count, description, horaires, contact, website, prix, price_level, duree, alerte, photo_credit, photo_source, tags, ideal_pour, photos, verified, infos_estimees) values ('parc-national-du-w', 'Parc national du W', 'site_touristique', 'Alibori', 'Bénin', 'Alibori', 'https://www.google.com/maps/search/?api=1&query=12.0408333,3.0341667', 'Vérifié (Google Places)', 12.0408333, 3.0341667, null, null, 'Partagé entre le Bénin, le Niger et le Burkina Faso et classé à l''UNESCO, le parc W doit son nom aux méandres du fleuve Niger. Éléphants, buffles, hippopotames et oiseaux d''eau y peuplent savanes et zones humides.', 'Ouvert toute l''année', null, null, 'Entrée ≈ 10 000 FCFA / 24 h, + véhicule (≈ 60 000 à 70 000 FCFA), guide (≈ 20 000 FCFA) et carburant', 'eleve', 'sejour', 'Zone formellement déconseillée aux voyageurs (risque d''attaques terroristes et d''enlèvements, frontière nord). Vérifiez les conseils aux voyageurs de votre pays avant tout déplacement.', null, null, array['faune','nature','aventure']::text[], array['couple','amis','famille']::text[], '{}'::text[], true, false) on conflict (slug) do update set nom = excluded.nom, category = excluded.category, department = excluded.department, country = excluded.country, address = excluded.address, google_maps_url = excluded.google_maps_url, source = excluded.source, lat = excluded.lat, lng = excluded.lng, rating = excluded.rating, reviews_count = excluded.reviews_count, description = excluded.description, horaires = excluded.horaires, contact = excluded.contact, website = excluded.website, prix = excluded.prix, price_level = excluded.price_level, duree = excluded.duree, alerte = excluded.alerte, photo_credit = excluded.photo_credit, photo_source = excluded.photo_source, tags = excluded.tags, ideal_pour = excluded.ideal_pour, photos = excluded.photos, verified = excluded.verified, infos_estimees = ex